let state, page = "dashboard", analytics = null, reportError = null, reportType = "month", reportPeriod = new Date().toISOString().slice(0, 7), reportFrom = new Date().toISOString().slice(0, 10), reportTo = new Date().toISOString().slice(0, 10), backups = null, healthStatus = null, billHistory = null, inventoryData = null, inventoryError = null, inventoryFilters = {}, posData = null, posOrder = null, posError = null, posHistory = [], posContext = { orderType:"WALK_IN", tableId:null }, reservationFormDirty = false, stateRefreshPromise = null;
const $ = s => document.querySelector(s);
// A table opened before midnight (Thai time, UTC+7) but paid after it must count toward the day it
// was OPENED, not the day the bill happened to close — mirrors billReportingTimestamp() in
// index.js. Walk-in bills have no play start, so those fall back to createdAt.
function thaiDateKey(iso){ return new Date(new Date(iso).getTime()+7*60*60*1000).toISOString().slice(0,10); }
function thaiTodayKey(){ return thaiDateKey(new Date().toISOString()); }
function billReportingDateKey(bill){ return thaiDateKey(bill.playStartedAt||bill.createdAt); }
const money = n => new Intl.NumberFormat("th-TH", { style:"currency", currency:"THB", minimumFractionDigits:0, maximumFractionDigits:0 }).format(Math.ceil(Number(n) || 0));
const time = s => new Date(s).toLocaleTimeString("th-TH", { hour:"2-digit", minute:"2-digit" });
const duration = n => `${String(Math.floor(n / 3600)).padStart(2,"0")}:${String(Math.floor(n % 3600 / 60)).padStart(2,"0")}:${String(n % 60).padStart(2,"0")}`;
async function api(url, options = {}) { const r = await fetch(url, { headers:{ "Content-Type":"application/json" }, ...options }); const contentType=r.headers.get("content-type")||"", isJson=contentType.includes("application/json"); let data; try { data=isJson ? await r.json() : await r.text(); } catch { data=null; } if (!r.ok) { const inventoryEndpoint=url.startsWith("/api/products")||url.startsWith("/api/product-categories"); const message=!isJson&&inventoryEndpoint ? "ไม่พบ API สำหรับจัดการสินค้า กรุณาตรวจสอบว่าเซิร์ฟเวอร์เป็นเวอร์ชันล่าสุด" : (isJson&&(data?.message||data?.error) ? (data.message||data.error) : "ไม่สามารถติดต่อ API ได้"); const error=Error(message); error.status=r.status; error.code=isJson?data?.error:undefined;if(isJson&&data?.emergency)error.emergency=data.emergency; console.error("API request failed",{url,status:r.status,code:error.code,message}); throw error; } if (!isJson) { const error=Error("API ตอบกลับข้อมูลไม่ถูกต้อง กรุณาตรวจสอบเซิร์ฟเวอร์"); error.status=r.status; throw error; } return data; }
