async function exportBackup(fileName){try{if(window.luckyDesktop?.exportBackup){const result=await window.luckyDesktop.exportBackup(fileName);notify(result.message|| (result.status==="CANCELLED"?"ยกเลิกการบันทึกไฟล์สำรองข้อมูลแล้ว":"บันทึกไฟล์สำรองข้อมูลสำเร็จ"));return;}const link=document.createElement("a");link.href=`/api/backups/${encodeURIComponent(fileName)}/download`;link.download=fileName;link.rel="noopener";document.body.appendChild(link);link.click();link.remove();}catch(_){notify("ไม่สามารถบันทึกไฟล์สำรองข้อมูลได้ กรุณาเลือกตำแหน่งอื่น",true);}}
