async function viewBillDetails(id){ try{ const data=await api(`/api/bills/${id}`); const b=data.bill, snapshot=b.pricingSnapshot||{}; const events=data.auditEvents.map(e=>`<li>${new Date(e.occurredAt).toLocaleString("th-TH")} — ${escapeHtml(e.event)} <small>(${escapeHtml(e.actorId||e.userId||"UNKNOWN")})</small></li>`).join("")||"<li>ไม่มี Audit Event ที่เชื่อมโยง</li>"; const payments=data.payments.map(p=>`${p.method||"qr"}: ${money(p.amount)} (${p.status}) ${p.paidAt?new Date(p.paidAt).toLocaleString("th-TH"):""}`).join("<br>")||"ยังไม่มีข้อมูลการชำระ"; openModal(`<h3>รายละเอียดบิล ${escapeHtml(b.receiptNumber||b.number)}</h3><p>โต๊ะ: <b>${escapeHtml(b.tableName)}</b><br>เริ่ม: ${b.playStartedAt?new Date(b.playStartedAt).toLocaleString("th-TH"):"-"}<br>สิ้นสุด: ${b.playEndedAt?new Date(b.playEndedAt).toLocaleString("th-TH"):"-"}<br>ระยะเวลา: ${Number.isFinite(b.playDurationSeconds)?duration(b.playDurationSeconds):"-"}</p><p>ราคาที่ใช้: ${Array.isArray(b.rateSegments)&&b.rateSegments.length?b.rateSegments.map(seg=>`${new Date(seg.from).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit"})}–${new Date(seg.to).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit"})} · ${money(seg.rateSatang/100)}/ชม. · ${money(seg.satang/100)}${seg.ruleName?" ("+escapeHtml(seg.ruleName)+")":""}`).join("<br>"):(snapshot.rateSatang?money(snapshot.rateSatang/100)+" / ชั่วโมง":"ไม่มี Snapshot")}<br>ก่อนปัด: ${money(((b.playAmountSatang||0)+(b.foodAmountSatang||0))/100)}<br>ยอดหลังปัด: <b>${money(b.total)}</b></p><p>วิธีชำระ / เวลาได้รับเงิน:<br>${payments}</p>${b.status==="void"?`<p class="danger">Void: ${escapeHtml(b.voidReason||"-")} (${escapeHtml(b.voidedBy||"UNKNOWN")})</p>`:""}<h4>Audit Events</h4><ul>${events}</ul></div>`); }catch(e){notify(e.message,true);} }
// Voiding a bill that carried products has to say what happened to the goods, because "void" alone
// leaves stock and revenue undecided. The tab option is offered only while the exact session the
// bill came from is still open — after the table closes, or reopens for the next customer, putting
// the drinks back would bill the wrong person, so the server refuses it too.
function voidModeChoices(bill){
  if(!bill.posOrderIds?.length) return "";
  const table=(state.tables||[]).find(item=>String(item.id)===String(bill.tableId));
  const tabOpen=Boolean(bill.partialOrdersOnly&&bill.tableSessionId&&table&&String(table.runtimeSessionId)===String(bill.tableSessionId));
  const option=(value,label,hint,{checked=false,disabled=false}={})=>`<label class="void-mode${disabled?" disabled":""}"><input type="radio" name="voidMode" value="${value}" ${checked?"checked":""} ${disabled?"disabled":""}><span><b>${label}</b><br><small>${hint}</small></span></label>`;
  return `<label>รายการสินค้าในบิลนี้จะให้ทำอย่างไร</label><div class="void-modes">
    ${option("RETURN_TO_TAB","เอากลับไปรวมบิลโต๊ะ",tabOpen?"ของส่งให้ลูกค้าแล้ว จะเก็บเงินตอนปิดโต๊ะ · สต็อกคงเดิม":"ใช้ไม่ได้ — โต๊ะปิดไปแล้ว หรือเปิดให้ลูกค้ารายใหม่แล้ว",{checked:tabOpen,disabled:!tabOpen})}
    ${option("CANCEL_RESTORE_STOCK","ยกเลิกการขาย คืนสต็อก","ลูกค้ายังไม่ได้รับของ · ของกลับเข้าคลัง ไม่เก็บเงิน",{checked:!tabOpen})}
    ${option("CANCEL_KEEP_STOCK","ยกเลิกบิล ไม่คืนสต็อก","ของถูกใช้ไปแล้วแต่ไม่เก็บเงิน (แถม/ของเสีย) · สต็อกคงเดิม")}
  </div>`;
}
function voidBillDialog(id){ const bill=(billHistory?.items||state.bills).find(item=>item.id===id); if(!bill) return; openModal(`<h3>Void บิล ${escapeHtml(bill.receiptNumber||bill.number)}</h3><p class="muted">ข้อมูลบิลและการชำระจะไม่ถูกลบ</p>${voidModeChoices(bill)}<label>เหตุผลการ Void</label><textarea id="voidReason" required></textarea><button class="danger" id="confirmVoid">ยืนยัน Void</button>`); $("#confirmVoid").onclick=async()=>{ const reason=$("#voidReason").value.trim(); if(!reason) return notify("กรุณาระบุเหตุผลการ Void",true); const voidMode=document.querySelector("input[name=voidMode]:checked")?.value; try{const result=await api(`/api/bills/${id}`,{method:"DELETE",body:JSON.stringify({reason,actorId:"SYSTEM",...(voidMode?{voidMode}:{})})}); closeModal(); await refresh(); await loadBillHistory(); render(); notify(result.message);}catch(e){notify(e.message,true);} }; }
async function tableSessionAction(tableId, action){ if(action==="cancel"&&!confirm("ยืนยันยกเลิก Session นี้? จะไม่สร้างยอดขาย")) return; try{ const result=await api(`/api/tables/${tableId}/${action}`,{method:"POST",body:"{}"}); await refresh(); notify(result.warning||({pause:"พักเวลาแล้ว",resume:"เล่นต่อแล้ว",cancel:"ยกเลิก Session แล้ว"}[action]),!!result.warning); }catch(error){ notify(error.message,true); } }
