async function restoreBackup(file){try{const dryRun=await api(`/api/backups/${encodeURIComponent(file)}/dry-run`,{method:"POST",body:"{}"});if(dryRun.status==="INVALID")return notify("ไฟล์สำรองไม่ผ่านการตรวจสอบ จึงไม่สามารถกู้คืนได้",true);if(!confirm(`ผลตรวจสอบ: ${dryRun.status}\nยืนยันกู้คืนข้อมูลจากไฟล์นี้?\nข้อมูลปัจจุบันจะถูกแทนที่ (ระบบจะสำรองข้อมูลปัจจุบันไว้ให้ก่อน)`))return;const result=await api(`/api/backups/${encodeURIComponent(file)}/restore`,{method:"POST",body:"{}"});await refresh();await loadBackups();analytics=null;render();notify(result.message);}catch(e){notify(e.message,true);} }
async function deleteBackup(file){ if(!confirm(`ยืนยันลบไฟล์สำรองข้อมูลนี้?`)) return; try{ const result=await api(`/api/backups/${encodeURIComponent(file)}`,{method:"DELETE"}); await loadBackups(); render(); notify(result.message); }catch(e){ notify(e.message,true); } }
async function loadAnalytics(){ try { reportError=null; const range=reportType==="range"?`&from=${encodeURIComponent(reportFrom)}&to=${encodeURIComponent(reportTo)}`:""; analytics=await api(`/api/reports/analytics?type=${encodeURIComponent(reportType)}&period=${encodeURIComponent(reportPeriod)}${range}`); } catch(e) { analytics=null; reportError=e.message||"ไม่สามารถโหลดรายงานได้"; } }
async function applyReportFilter(e){ e.preventDefault(); const d=Object.fromEntries(new FormData(e.target)); reportType=d.type; if(reportType==="range"){ if(d.from) reportFrom=d.from; if(d.to) reportTo=d.to; if(reportFrom>reportTo) [reportFrom,reportTo]=[reportTo,reportFrom]; } else if(d.period) reportPeriod=d.period; analytics=null; render(); await loadAnalytics(); render(); }
function startDialog(id){ openModal(`<h3>เปิด ${state.tables.find(t=>t.id==id).name}</h3><label>ผูกสมาชิก (ไม่บังคับ)</label><select id="memberChoice"><option value="">ลูกค้าทั่วไป</option>${state.members.map(m=>`<option value="${m.id}">${m.code} — ${m.name}</option>`).join("")}</select><button id="confirmStart">เริ่มจับเวลาและเปิด Relay</button>`); $("#confirmStart").onclick=async()=>{try{const data=await api(`/api/tables/${id}/start`,{method:"POST",body:JSON.stringify({memberId:$("#memberChoice").value||null})});closeModal();await refresh();notify(data.warning||"เปิดโต๊ะและสั่งเปิด Relay แล้ว",!!data.warning);}catch(e){notify(e.message,true)}}; }
async function orderDialog(id){ const table=state.tables.find(item=>String(item.id)===String(id)); if(!table)return; posContext={orderType:"TABLE",tableId:String(table.id)}; localStorage.setItem(`lucky_pos_context_${state.user.userId}`,JSON.stringify(posContext)); page="pos"; await loadPos(); render(); }
function checkoutDialog(id){ const t=state.tables.find(t=>t.id==id), food=t.items.reduce((s,i)=>s+i.price*i.quantity,0); openModal(`<h3>คิดเงิน ${t.name}</h3><p>ค่าโต๊ะ: ${money(t.currentPrice)}<br>อาหาร/เครื่องดื่ม: ${money(food)}</p><div class="total">รวมโดยประมาณ ${money(t.currentPrice+food)}</div><div class="actions"><button id="cash">เงินสด</button><button id="transfer">โอนเงิน</button></div>`); $("#cash").onclick=()=>checkout(id,"cash"); $("#transfer").onclick=()=>checkout(id,"transfer"); }
async function checkout(id,method){ try{const data=await api(`/api/tables/${id}/checkout`,{method:"POST",body:JSON.stringify({paymentMethod:method})}); openModal(`<h3>ยืนยันรับชำระ</h3><p>บิล <b>${data.bill.number}</b></p><p>วิธีชำระ: ${method==="transfer"?"โอนเงิน":"เงินสด"}</p><div class="total">ยอดรับชำระ ${money(data.payment.amount)}</div><p class="muted">โต๊ะจะถูกปิดหลังยืนยันการชำระเงิน</p><div class="actions"><button id="confirmPay">ยืนยันรับชำระ</button><button class="outline" id="cancelPay">ยกเลิกรายการชำระ</button></div>`); $("#confirmPay").onclick=async()=>{try{const confirmed=await api(`/api/payments/${data.payment.id}/confirm`,{method:"POST"});closeModal();await refresh();notify(confirmed.warning||"ชำระเงินแล้วและปิด Relay",!!confirmed.warning);offerPrint(data.bill.id);}catch(e){notify(e.message,true);}}; $("#cancelPay").onclick=async()=>{try{await api(`/api/payments/${data.payment.id}/cancel`,{method:"POST"});closeModal();await refresh();notify("ยกเลิกรายการชำระแล้ว");}catch(e){notify(e.message,true);}};}catch(e){notify(e.message,true)} }
async function deleteBill(id){ const bill=state.bills.find(b=>b.id===id); if(!bill || !confirm(`ยืนยันยกเลิกบิล ${bill.number}?\nข้อมูลเดิมจะถูกเก็บไว้ในประวัติการตรวจสอบ`)) return; try { const result=await api(`/api/bills/${id}`,{method:"DELETE"}); analytics=null; await refresh(); notify(result.message); } catch(e) { notify(e.message,true); } }
function escapeHtml(value){ return String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;","\"":"&quot;"})[char]); }
function offerPrint(billId){ const bill=state.bills.find(b=>b.id===billId); if(!bill) return; openModal(`<h3>ชำระเงินสำเร็จ</h3><p>บิล <b>${bill.number}</b> ยอด ${money(bill.total)}</p><p>ต้องการพิมพ์ใบเสร็จให้ลูกค้าหรือไม่?</p><div class="actions"><button id="printNow">พิมพ์ใบเสร็จ</button><button class="outline" id="skipPrint">ไม่พิมพ์ตอนนี้</button></div>`); $("#printNow").onclick=()=>{closeModal();printBill(billId);}; $("#skipPrint").onclick=closeModal; }
function printBill(id){ const bill=state.bills.find(b=>b.id===id); if(!bill) return; const popup=window.open("","receipt","width=420,height=700"); if(!popup){ notify("เบราว์เซอร์บล็อกหน้าต่างพิมพ์ กรุณาอนุญาตป๊อปอัป",true); return; } const items=(bill.items||[]).map(i=>`<tr><td>${escapeHtml(i.name)} × ${i.quantity}</td><td class="right">${money(i.total)}</td></tr>`).join("")||"<tr><td colspan=\"2\" class=\"small\">ไม่มีรายการอาหาร/เครื่องดื่ม</td></tr>"; const payment=bill.paymentMethod==="transfer"?"โอนเงิน":bill.paymentMethod==="qr"?"QR Payment":"เงินสด"; const start=bill.playStartedAt?new Date(bill.playStartedAt).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"-"; const end=bill.playEndedAt?new Date(bill.playEndedAt).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"-"; const played=Number.isFinite(bill.playDurationSeconds)?duration(bill.playDurationSeconds):"-"; popup.document.write(`<!doctype html><html lang="th"><head><meta charset="utf-8"><title>ใบเสร็จ ${escapeHtml(bill.number)}</title><style>@page{size:58mm auto;margin:0}*{box-sizing:border-box}body{width:44mm;margin:0;padding:2mm;font-family:Arial,"Tahoma",sans-serif;color:#000;font-size:12px}.center{text-align:center}.right{text-align:right}h2{font-size:17px;margin:0 0 4px}.line{border-top:1px dashed #000;margin:9px 0}table{width:100%;border-collapse:collapse;table-layout:fixed}td{padding:3px 0;overflow-wrap:break-word;word-wrap:break-word}.total{font-weight:bold;font-size:15px}.small{font-size:10px}@media print{body{width:44mm}}</style></head><body><div class="center"><h2>${escapeHtml(state.settings.shopName)}</h2><div>ใบเสร็จรับเงิน</div><div class="small">เลขที่ ${escapeHtml(bill.number)}</div></div><div class="line"></div><table><tr><td>วันที่</td><td class="right">${new Date(bill.createdAt).toLocaleString("th-TH")}</td></tr><tr><td>โต๊ะ</td><td class="right">${escapeHtml(bill.tableName)}</td></tr><tr><td>ลูกค้า</td><td class="right">${escapeHtml(bill.memberName)}</td></tr><tr><td>เริ่มเล่น</td><td class="right">${start}</td></tr><tr><td>หยุดเล่น</td><td class="right">${end}</td></tr><tr><td>เวลาเล่นรวม</td><td class="right">${played}</td></tr></table><div class="line"></div><table>${items}<tr><td>ค่าเวลาโต๊ะ</td><td class="right">${money(bill.playAmount)}</td></tr><tr><td>อาหาร/เครื่องดื่ม</td><td class="right">${money(bill.foodAmount)}</td></tr></table><div class="line"></div><table class="total"><tr><td>รวมทั้งสิ้น</td><td class="right">${money(bill.total)}</td></tr><tr class="small"><td>ชำระโดย</td><td class="right">${payment}</td></tr></table><div class="line"></div><div class="center small">ขอบคุณที่ใช้บริการ</div><div id="receiptExtensionPoint"></div></body></html>`); popup.document.close(); setTimeout(()=>{popup.focus();popup.print();},0); }
