// Sprint 9A.1: member management is server-backed; UI permissions only improve usability.
// Per-column filters, shared by the member and product tables.
//
// They run on rows already in the page rather than round-tripping: /api/members returns the whole
// matching set with no pagination, and the product list is fetched in one page, so everything the
// filter could match is already here. That makes filtering instant and — more importantly — means
// the visible result can never disagree with what a server query would have returned.
//
// Matching reads data-* attributes off the row, never the rendered text: "฿1,234" has to compare as
// a number and "20/8/2569" as a date, and the columns that show a badge instead of a value (stock)
// have no useful text to match at all.
let columnFilters={members:{},products:{}};
const COLUMN_FILTER_OPS={
  text:(cell,value)=>cell.includes(value),
  equals:(cell,value)=>cell===value,
  min:(cell,value)=>Number(cell||0)>=Number(value),
  from:(cell,value)=>Boolean(cell)&&cell>=value
};
function applyColumnFilters(scopeSelector,scopeName){
  const scope=document.querySelector(scopeSelector);
  if(!scope)return;
  const active=Array.from(scope.querySelectorAll("[data-filter-key]")).filter(control=>String(control.value).trim()!=="");
  const rows=Array.from(scope.querySelectorAll("tr[data-row]"));
  let shown=0;
  rows.forEach(row=>{
    const visible=active.every(control=>{
      const cell=String(row.dataset[control.dataset.filterKey]||"").toLowerCase();
      return COLUMN_FILTER_OPS[control.dataset.filterOp||"text"](cell,String(control.value).trim().toLowerCase());
    });
    row.classList.toggle("hidden",!visible);
    if(visible)shown+=1;
  });
  const counter=scope.querySelector("[data-filter-count]");
  if(counter)counter.textContent=active.length?`แสดง ${shown} จาก ${rows.length} รายการ`:`${rows.length} รายการ`;
  const clear=scope.querySelector("[data-filter-clear]");
  if(clear)clear.classList.toggle("hidden",!active.length);
  const empty=scope.querySelector("[data-filter-empty]");
  if(empty)empty.classList.toggle("hidden",Boolean(shown)||!rows.length);
  if(scopeName)columnFilters[scopeName]=Object.fromEntries(active.map(control=>[control.dataset.filterKey,control.value]));
}
// Re-applied after every render because the tables are rebuilt from scratch whenever a row action
// runs — without this, changing one member's status would silently drop the filters the user set.
function bindColumnFilters(scopeSelector,scopeName){
  const scope=document.querySelector(scopeSelector);
  if(!scope)return;
  scope.querySelectorAll("[data-filter-key]").forEach(control=>{
    const run=()=>applyColumnFilters(scopeSelector,scopeName);
    control.oninput=run;control.onchange=run;
  });
  const clear=scope.querySelector("[data-filter-clear]");
  if(clear)clear.onclick=()=>{scope.querySelectorAll("[data-filter-key]").forEach(control=>{control.value="";});columnFilters[scopeName]={};applyColumnFilters(scopeSelector,scopeName);};
  applyColumnFilters(scopeSelector,scopeName);
}
const colText=(scope,key,placeholder="")=>`<input class="col-filter" data-filter-key="${key}" data-filter-op="text" value="${escapeHtml(columnFilters[scope][key]||"")}" placeholder="${escapeHtml(placeholder)}" aria-label="กรอง ${escapeHtml(placeholder||key)}">`;
const colMin=(scope,key)=>`<input class="col-filter" type="number" min="0" step="any" data-filter-key="${key}" data-filter-op="min" value="${escapeHtml(columnFilters[scope][key]||"")}" placeholder="ตั้งแต่" aria-label="กรองตั้งแต่">`;
const colFrom=(scope,key)=>`<input class="col-filter" type="date" data-filter-key="${key}" data-filter-op="from" value="${escapeHtml(columnFilters[scope][key]||"")}" aria-label="กรองตั้งแต่วันที่">`;
const colPick=(scope,key,options,anyLabel)=>`<select class="col-filter" data-filter-key="${key}" data-filter-op="equals" aria-label="${escapeHtml(anyLabel)}"><option value="">${escapeHtml(anyLabel)}</option>${options.map(option=>{const value=typeof option==="string"?option:option.value,label=typeof option==="string"?option:option.label;return `<option value="${escapeHtml(value)}" ${String(columnFilters[scope][key]||"")===String(value)?"selected":""}>${escapeHtml(label)}</option>`;}).join("")}</select>`;
const colFilterNote=`<div class="col-filter-note"><span data-filter-count></span><button type="button" class="outline hidden" data-filter-clear>ล้างตัวกรอง</button></div>`;
let memberUi={items:null,error:null,search:"",status:"",tier:""};
