  if(step===2)openModal(wizardShell(2,`<h3>ค้นหากล่องควบคุม</h3><p>กรอกเลขที่แสดงในหน้าข้อมูลเครือข่ายของกล่อง</p><label>เลขอุปกรณ์ในเครือข่าย</label><input id="wizardHost" inputmode="decimal" placeholder="192.168.1.191" value="${escapeHtml(hardwareLastHost)}"><details><summary>ดูวิธีหาเลขอุปกรณ์</summary><p>เปิดหน้ารายชื่ออุปกรณ์ในเราเตอร์ มองหาชื่อ Lucky Relay Controller แล้วคัดลอกเลขรูปแบบ 192.168.x.x คอมพิวเตอร์ใช้ Wi-Fi 5 GHz ได้ หากอยู่เราเตอร์เดียวกับกล่องที่ใช้ 2.4 GHz</p></details><div id="wizardError" class="wizard-error"></div>`,`<button class="outline" id="wizardBack">ย้อนกลับ</button><button id="wizardVerify">ค้นหาและตรวจสอบ</button>`));
