printBill=function(id){const bill=state.bills.find(item=>item.id===id);if(!bill)return;const popup=window.open("","receipt","width=420,height=700");if(!popup)return notify("เบราว์เซอร์บล็อกหน้าต่างพิมพ์ กรุณาอนุญาตป๊อปอัป",true);const drink=item=>/drink|beverage|เครื่องดื่ม/i.test(String(item.categoryName||item.category||item.categoryId||""));const rows=list=>list.map(item=>`<tr><td>${escapeHtml(item.name)} × ${item.quantity}</td><td class="right">${money(item.total)}</td></tr>`).join("");const drinks=(bill.items||[]).filter(drink),foods=(bill.items||[]).filter(item=>!drink(item));const productRows=`${drinks.length?`<tr><td colspan="2"><b>เครื่องดื่ม</b></td></tr>${rows(drinks)}`:""}${foods.length?`<tr><td colspan="2"><b>อาหาร / รายการอื่น</b></td></tr>${rows(foods)}`:""}`||"<tr><td colspan=\"2\">ไม่มีรายการสินค้า</td></tr>";const start=bill.playStartedAt?new Date(bill.playStartedAt).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"-",end=bill.playEndedAt?new Date(bill.playEndedAt).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"-",played=Number.isFinite(bill.playDurationSeconds)?duration(bill.playDurationSeconds):"-";popup.document.write(`<!doctype html><meta charset="utf-8"><style>@page{size:58mm auto;margin:0}*{box-sizing:border-box}body{width:44mm;margin:0;padding:2mm;font:12px Arial}.right{text-align:right}.line{border-top:1px dashed;margin:8px 0}table{width:100%;border-collapse:collapse;table-layout:fixed}td{padding:3px 0;overflow-wrap:break-word;word-wrap:break-word}.total{font-weight:bold;font-size:15px}</style><div style="text-align:center"><b>${escapeHtml(state.settings.shopName)}</b><br>ใบเสร็จรับเงิน<br>${escapeHtml(bill.number)}</div><div class="line"></div><table><tr><td>โต๊ะ</td><td class="right">${escapeHtml(bill.tableName)}</td></tr><tr><td>เริ่มเล่น</td><td class="right">${start}</td></tr><tr><td>หยุดเล่น</td><td class="right">${end}</td></tr><tr><td>เวลาเล่นรวม</td><td class="right">${played}</td></tr></table><div class="line"></div><table><tr><td colspan="2"><b>ค่าโต๊ะ</b></td></tr><tr><td>ค่าบริการโต๊ะ</td><td class="right">${money(bill.playAmount)}</td></tr>${productRows}</table><div class="line"></div><table class="total"><tr><td>รวมทั้งสิ้น</td><td class="right">${money(bill.total)}</td></tr></table><div id="receiptExtensionPoint"></div>`);popup.document.close();setTimeout(()=>{popup.focus();popup.print();},0);};

