function rewardPanel(preview){if(preview.saleSource==="WALK_IN"||!preview.memberId||!["OWNER","MANAGER","CASHIER"].includes(state.user.role))return "";return `<div class="card" id="rewardPanel"><h3>Member Rewards</h3><p id="rewardBalance" class="muted">กำลังโหลดสิทธิ์ใช้แต้ม…</p><label>ใช้แต้ม</label><input id="redeemedPoints" type="number" min="0" step="1" value="0"><div class="actions"><button type="button" id="rewardUseMax">ใช้สูงสุด</button><button type="button" id="rewardPreview">คำนวณส่วนลด</button></div><p id="rewardResult" class="muted"></p></div>`;}
async function bindRewardPanel(preview){const input=$("#redeemedPoints");if(!input)return;const request=async points=>api("/api/rewards/preview",{method:"POST",body:JSON.stringify({memberId:preview.memberId,totalSatang:preview.totalSatang||preview.breakdown?.totalSatang,total:preview.total||preview.breakdown?.total,saleSource:preview.saleSource||"TABLE",points})});try{const initial=await request(0);$("#rewardBalance").textContent=`แต้มคงเหลือ ${initial.memberBalance} · ใช้ได้สูงสุด ${initial.maximumPoints} แต้ม`;const show=async points=>{const result=await request(points);$("#rewardResult").textContent=`ส่วนลด ${money(result.discount)} · ยอดสุทธิ ${money(result.netTotal)}`;return result;};$("#rewardUseMax").onclick=async()=>{try{const r=await initial;input.value=r.maximumPoints;await show(r.maximumPoints);}catch(e){notify(e.message,true);}};$("#rewardPreview").onclick=async()=>{try{await show(input.value);}catch(e){notify(e.message,true);}};}catch(error){$("#rewardBalance").textContent=error.message;}}
checkoutDialog=async function(id){const table=state.tables.find(item=>String(item.id)===String(id));if(!table?.runtimeSessionId)return notify("ไม่พบ Session ที่พร้อมคิดเงิน",true);try{const data=await api(`/api/table-sessions/${table.runtimeSessionId}/billing-preview`),preview=data.preview,b=preview.breakdown,interval=(state.settings.loyalty?.tablePointIntervalMinutes||60)*60,estimated=Math.floor(Number(preview.playDurationSeconds||0)/interval)*(state.settings.loyalty?.tablePointsPerHour||5);openModal(`<h3>ตัวอย่างบิลรวม — ${escapeHtml(table.name)}</h3><p>ค่าโต๊ะ: <b>${money(b.tableCharge)}</b><br>อาหาร/เครื่องดื่ม: <b>${money(b.products)}</b><br>เวลาเล่น: <b>${duration(preview.playDurationSeconds||0)}</b><br>แต้มโดยประมาณหลังชำระ: <b>${preview.memberId?estimated:0} แต้ม</b></p><div class="total">รวม ${money(b.total)}</div>${rewardPanel(preview)}<label>วิธีชำระเงิน</label><select id="combinedPaymentMethod"><option value="cash">เงินสด</option><option value="transfer">โอนเงิน</option><option value="qr">QR Payment</option></select><div class="actions"><button class="outline" id="cancelCombinedPreview">กลับ</button><button class="success" id="confirmCombinedBill">ยืนยันสร้างบิล</button></div>`);await bindRewardPanel(preview);$("#cancelCombinedPreview").onclick=closeModal;$("#confirmCombinedBill").onclick=async()=>{const button=$("#confirmCombinedBill");button.disabled=true;try{const created=await api(`/api/table-sessions/${table.runtimeSessionId}/create-bill`,{method:"POST",body:JSON.stringify({paymentMethod:$("#combinedPaymentMethod").value,...normalizedRewardPayload(preview)})});closeModal();await refresh();openPaymentConfirmation(created.bill,created.payment);}catch(e){console.error("Combined bill creation failed",e);notify(e.message,true);button.disabled=false;}};}catch(e){notify(e.message,true);}};
walkInCheckout=async function(orderId){try{const preview=await api(`/api/pos-orders/${orderId}/billing-preview`);openModal(`<h3>ตัวอย่างบิลขายหน้าร้าน</h3><p>เลขรายการ: <b>${escapeHtml(preview.orderNumber)}</b></p><div class="total">รวม ${money(preview.total)}</div>${rewardPanel(preview)}<label>วิธีชำระเงิน</label><select id="walkInPaymentMethod"><option value="cash">เงินสด</option><option value="transfer">โอนเงิน</option><option value="qr">QR Payment</option></select><div class="actions"><button class="outline" id="cancelWalkIn">กลับ</button><button class="success" id="createWalkInBill">ยืนยันสร้างบิล</button></div>`);await bindRewardPanel(preview);$("#cancelWalkIn").onclick=closeModal;$("#createWalkInBill").onclick=async()=>{const button=$("#createWalkInBill");button.disabled=true;try{const created=await api(`/api/pos-orders/${orderId}/create-bill`,{method:"POST",body:JSON.stringify({paymentMethod:$("#walkInPaymentMethod").value,...normalizedRewardPayload(preview)})});closeModal();await refresh();openWalkInPaymentConfirmation(created.bill,created.payment,orderId);}catch(e){console.error("Walk-in bill creation failed",e);notify(e.message,true);button.disabled=false;}};}catch(e){notify(e.message,true);}};

