const bindReservations10=bind;bind=function(){bindReservations10();const form=$("#reservationForm");if(form)form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));d.amountSatang=Math.round(Number(d.depositAmount)*100);d.paymentConfirmed=form.elements.paymentConfirmed.checked;delete d.depositAmount;try{await api("/api/reservations",{method:"POST",body:JSON.stringify(d)});form.reset();reservationFormDirty=false;await refresh();notify("สร้างการจองแล้ว");}catch(x){notify(x.message,true);}};document.querySelectorAll("[data-res-checkin]").forEach(b=>b.onclick=async()=>{try{await api(`/api/reservations/${b.dataset.resCheckin}/check-in`,{method:"PATCH",body:"{}"});await refresh();notify("Check-in แล้ว");}catch(x){notify(x.message,true);}});document.querySelectorAll("[data-res-cancel]").forEach(b=>b.onclick=async()=>{if(!confirm("ยืนยันยกเลิกการจอง? มัดจำจะยังคง AVAILABLE"))return;try{await api(`/api/reservations/${b.dataset.resCancel}/cancel`,{method:"PATCH",body:"{}"});await refresh();notify("ยกเลิกการจองแล้ว");}catch(x){notify(x.message,true);}});document.querySelectorAll("[data-deposit-action]").forEach(b=>b.onclick=async()=>{const reason=prompt("ระบุเหตุผล (จำเป็น)");if(!reason?.trim())return;try{await api(`/api/reservation-deposits/${b.dataset.depositId}/${b.dataset.depositAction}`,{method:"PATCH",body:JSON.stringify({reason})});await refresh();notify("อัปเดตมัดจำแล้ว");}catch(x){notify(x.message,true);}});const sf=$("#reservationSettingsForm");if(sf)sf.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(sf));["defaultDepositAmount","minimumDepositAmount","checkInGraceMinutes"].forEach(k=>d[k]=Number(d[k]));["depositRequired","autoAssignTable","autoLightOn","allowLightBeforeCheckIn"].forEach(k=>d[k]=sf.elements[k].checked);try{await api("/api/settings",{method:"PUT",body:JSON.stringify({reservation:d})});await refresh();notify("บันทึก Reservation Settings แล้ว");}catch(x){notify(x.message,true);}};};

