const printBillSettlement10b=printBill;printBill=function(id){const bill=state.bills.find(x=>x.id===id);if(!bill?.depositId)return printBillSettlement10b(id);const originalOpen=window.open;window.open=function(...args){const popup=originalOpen.apply(window,args);if(!popup)return popup;const originalWrite=popup.document.write.bind(popup.document);popup.document.write=html=>{const settlement=`<div class="line"></div><table><tr><td>ยอดบิลก่อนมัดจำ</td><td class="right">${money((bill.grossTotalSatang||bill.totalSatang)/100)}</td></tr><tr><td>มัดจำการจอง</td><td class="right">-${money((bill.depositAppliedSatang||0)/100)}</td></tr><tr class="total"><td>ยอดรับชำระคงเหลือ</td><td class="right">${money((bill.remainingPaymentSatang||0)/100)}</td></tr><tr><td>วิธีชำระ</td><td class="right">${escapeHtml(bill.paymentMethod||"-")}</td></tr><tr><td>ยอดรวมบิล</td><td class="right">${money((bill.grossTotalSatang||bill.totalSatang)/100)}</td></tr></table>`;originalWrite(String(html).replace('<div id="receiptExtensionPoint"></div>',`${settlement}<div id="receiptExtensionPoint"></div>`));};return popup;};try{return printBillSettlement10b(id);}finally{window.open=originalOpen;}};
