const bindReservationCancel10c=bind;bind=function(){bindReservationCancel10c();document.querySelectorAll("[data-res-cancel]").forEach(button=>button.onclick=()=>{const id=button.dataset.resCancel;openModal(`<h3>ยกเลิกการจอง</h3><p>มัดจำจะยังคงเป็นเครดิต AVAILABLE และจะไม่คืนเงินอัตโนมัติ</p><div class="actions"><button class="outline" id="cancelReservationNo">กลับ</button><button class="danger" id="cancelReservationYes">ยืนยันยกเลิก</button></div>`);$("#cancelReservationNo").onclick=closeModal;$("#cancelReservationYes").onclick=async()=>{const yes=$("#cancelReservationYes");yes.disabled=true;try{await api(`/api/reservations/${id}/cancel`,{method:"PATCH",body:"{}"});closeModal();await refresh();notify("ยกเลิกการจองแล้ว");}catch(error){notify(error.message,true);yes.disabled=false;}};});};
const bindReservationMember10c=bind;bind=function(){bindReservationMember10c();const form=$("#reservationForm");if(!form||$("#reservationMemberSearch"))return;const block=document.createElement("div");block.innerHTML=`<label>สมาชิก (ไม่บังคับ)</label><input id="reservationMemberSearch" placeholder="ค้นหารหัส ชื่อ หรือโทรศัพท์" autocomplete="off"><input name="memberId" id="reservationMemberId" type="hidden"><div id="reservationMemberResults" class="muted"></div><small id="reservationMemberPhoneHint" class="member-phone-hint"></small><button type="button" id="reservationMemberClear" class="outline hidden">ล้างสมาชิก</button>`;form.insertBefore(block,form.querySelector("label[for], textarea")||form.lastElementChild);let timer;$("#reservationMemberSearch").oninput=e=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=e.target.value.trim();if(!q){$("#reservationMemberResults").textContent="";return;}try{const data=await api(`/api/members/search?status=ACTIVE&search=${encodeURIComponent(q)}`);$("#reservationMemberResults").innerHTML=(data.items||[]).slice(0,6).map(m=>`<button type="button" data-res-member="${m.id}">${escapeHtml(m.memberCode||m.code||"")} — ${escapeHtml(m.displayName||m.name||"")} · ${escapeHtml(m.phone||"")}</button>`).join("")||"ไม่พบสมาชิก";document.querySelectorAll("[data-res-member]").forEach(button=>button.onclick=()=>{const m=(data.items||[]).find(x=>x.id===button.dataset.resMember);$("#reservationMemberId").value=m.id;$("#reservationMemberSearch").value=`${m.memberCode||m.code||""} — ${m.displayName||m.name||""}`;$("#reservationMemberResults").textContent=`เลือกสมาชิก: ${m.displayName||m.name||""}`;applyReservationMember10f(m);reservationFormDirty=true;});}catch(error){$("#reservationMemberResults").textContent=error.message;}},250);};};

// Final UI projection: deadline remains server-only; a reservation card never renders a countdown.
function reservationDisplayOrder(items){const createdTime=item=>{const created=item.createdAt||(item.timeline||[]).find(event=>event.event==="RESERVATION_CREATED")?.occurredAt||item.reservedAt,time=Date.parse(created);return Number.isFinite(time)?time:0;};return [...(items||[])].sort((a,b)=>createdTime(b)-createdTime(a));}
reservationCardsHtml=function(){const deposits=state.reservationDeposits||[],canCheckIn=["OWNER","MANAGER","CASHIER","STAFF"].includes(state.user.role),canManage=["OWNER","MANAGER","CASHIER"].includes(state.user.role);return reservationDisplayOrder(state.reservations).map(item=>{const deposit=deposits.find(x=>x.reservationId===item.id),table=state.tables.find(x=>String(x.id)===String(item.assignedTableId));return `<div class="card"><h3>${escapeHtml(item.reservationNumber)}</h3><p><b>${escapeHtml(item.customerName)}</b>${item.memberCode?` · ${escapeHtml(item.memberCode)}`:""}<br>${escapeHtml(item.phone)}<br>${new Date(item.effectiveReservationAt||item.reservedAt).toLocaleString("th-TH")}<br>มัดจำ: ${money((deposit?.amountSatang||0)/100)} (${escapeHtml(deposit?.status||"-")})<br>โต๊ะ: ${escapeHtml(table?.name||"-")}</p><span class="badge">${escapeHtml(item.status)}</span><div class="actions">${canCheckIn&&item.status==="OPENED_WAITING_CHECK_IN"?`<button class="success" data-res-checkin10c="${item.id}">CHECK-IN</button>`:""}${canManage&&["BOOKED","AWAITING_DECISION","DEFERRED","WAITING_TABLE"].includes(item.status)?`<button class="danger" data-res-cancel="${item.id}">ยกเลิก</button>`:""}</div></div>`;}).join("")||'<div class="card muted">ยังไม่มีรายการจอง</div>';};
setInterval(()=>{if(!state||reservationPollingPaused)return;if(page==="reservations"&&!reservationFormDirty)refresh().catch(error=>console.error("Reservation polling failed",error));else loadReservationAlerts();},30000);

// Sprint 11A Hardware Manager: all ESP32 traffic stays behind the server-side HAL.
let hardwareDevices=[],hardwareTimer=null,hardwarePollingBusy=false;
function hardwareAllowed(){return ["OWNER","ADMIN"].includes(state?.user?.role);}
// Background re-renders (health polling) blindly replace #app's innerHTML, which destroys and
// recreates every <select>/<input> on the page — including a native dropdown popup the user
// currently has open, or mid-typing keystrokes. That silently "eats" the interaction (the user
// sees a dropdown/input that stops responding). Skip a background re-render while the user is
// actively focused in a form control or has a modal open; the fetched data is still kept so the
// next safe render (page change, modal close, or a subsequent poll once focus moves on) is fresh.
function backgroundRenderSafe(){const el=document.activeElement;if(el&&["INPUT","SELECT","TEXTAREA"].includes(el.tagName))return false;return $("#modal").classList.contains("hidden");}
async function loadHardware(silent=false){if(!hardwareAllowed())return;try{const data=await api("/api/hardware/devices");hardwareDevices=data.devices||[];if(page==="hardware")render();}catch(error){if(!silent)notify(error.message,true);}}
function stopHardwarePolling(){if(hardwareTimer){clearInterval(hardwareTimer);hardwareTimer=null;}}
async function pollHardwareHealth(){if(hardwarePollingBusy||page!=="hardware"||!hardwareAllowed())return;hardwarePollingBusy=true;try{const data=await api('/api/hardware/health/check-all',{method:'POST',body:'{}'});hardwareDevices=data.devices||hardwareDevices;if(page==='hardware'&&backgroundRenderSafe())render();}catch(error){console.error('Hardware health polling failed',{code:error.code||'HEALTH_POLL_FAILED'});}finally{hardwarePollingBusy=false;}}
function startHardwarePolling(){if(hardwareTimer||page!=="hardware"||!hardwareAllowed())return;pollHardwareHealth();hardwareTimer=setInterval(pollHardwareHealth,15000);}
function hardwareBadge(status,lastErrorCode){const labels={ONLINE:"✓ ออนไลน์",OFFLINE:"✕ ออฟไลน์",CHECKING:"… กำลังตรวจสอบ",STALE:"! ไม่ได้ตรวจมานาน",TIMEOUT:"⌛ หมดเวลาติดต่อ",UNKNOWN:lastErrorCode==='DEVICE_ID_MISMATCH'||lastErrorCode==='RELAY_COUNT_MISMATCH'?"! ข้อมูลอุปกรณ์ไม่ตรง":"? ยังไม่ทราบสถานะ",WARNING:"! คำเตือน",ERROR:"✕ ผิดพลาด",REPLACED_ARCHIVED:"🗄 เปลี่ยนแทนแล้ว"};return `<span class="hardware-badge hw-${String(status||"UNKNOWN").toLowerCase()}">${labels[status]||labels.UNKNOWN}</span>`;}
function hardware(){
  const liveDevices=hardwareDevices.filter(device=>device.status!=="REPLACED_ARCHIVED");
  const archivedDevices=hardwareDevices.filter(device=>device.status==="REPLACED_ARCHIVED");
  const cards=liveDevices.map(device=>`<div class="card hardware-device">
    <div class="actions"><h3>${escapeHtml(device.deviceName)}</h3>${hardwareBadge(device.status,device.lastErrorCode)}</div>
    <p><b>Device ID:</b> ${escapeHtml(device.deviceId||"-")}<br><b>IP:</b> ${escapeHtml(device.ipAddress)}:${device.port}<br><b>API Key:</b> ${device.apiKeyMasked}<br><b>Relay:</b> ${device.relayCount||"-"} ช่อง<br><b>Firmware / API:</b> ${escapeHtml(device.firmwareVersion||"-")} / ${escapeHtml(device.apiVersion||"-")}<br><b>ออนไลน์ล่าสุด:</b> ${device.lastSeen?new Date(device.lastSeen).toLocaleString("th-TH"):"-"}<br><b>ตรวจล่าสุด:</b> ${device.lastCheckedAt?new Date(device.lastCheckedAt).toLocaleString("th-TH"):"-"}</p>
    <div class="hardware-metrics"><span>Uptime: ${device.health?.uptimeSeconds??"-"} วินาที</span><span>RSSI: ${device.health?.rssi??"-"} dBm</span><span>Latency: ${device.health?.latencyMs??"-"} ms</span>${device.status!=="ONLINE"?`<span>ล้มเหลวต่อเนื่อง: ${device.consecutiveFailures||0}</span>`:""}</div>${device.lastErrorCode?`<p class="hardware-health-message"><b>${hardwareBadge(device.status,device.lastErrorCode)}</b><br>${escapeHtml(device.healthRecoverySuggestion||"ตรวจสายไฟและ Wi-Fi แล้วลองใหม่")}</p>`:""}
    <label>Relay Count</label><select data-hw-count="${device.id}">${[2,4,8].map(n=>`<option value="${n}" ${n===device.relayCount?"selected":""}>${n}</option>`).join("")}</select>
    <label>ขั้ว Relay (Polarity)</label><select data-hw-polarity="${device.id}"><option value="low" ${!device.relayActiveHigh?"selected":""}>Active-Low (ค่าเริ่มต้น)</option><option value="high" ${device.relayActiveHigh?"selected":""}>Active-High</option></select>
    <div class="relay-test-grid">${Array.from({length:Number(device.relayCount)||0},(_,i)=>i+1).map(channel=>`<div><small>Relay ${channel}</small><button data-hw-relay="${device.id}" data-channel="${channel}" data-state="true" ${device.status!=="ONLINE"?"disabled":""}>ON</button><button class="outline" data-hw-relay="${device.id}" data-channel="${channel}" data-state="false" ${device.status!=="ONLINE"?"disabled":""}>OFF</button></div>`).join("")}</div>
    <div class="actions"><button data-hw-test="${device.id}">ทดสอบ/รีเฟรช</button><button class="outline" data-hw-wiring="${device.id}" ${device.status!=="ONLINE"?"disabled":""}>ตรวจสอบการต่อสาย</button><button class="outline" data-hw-key-enroll="${device.id}">สร้างรหัสอุปกรณ์เฉพาะกล่อง</button><button class="outline" data-hw-setup-code="${device.id}">${device.hasSetupCode?"เปลี่ยน Setup Code":"สร้าง Setup Code"}</button><button class="outline" data-hw-setup-mode="${device.id}" ${device.status!=="ONLINE"?"disabled":""}>โหมดกู้คืน Wi-Fi</button><button class="outline" data-hw-wifi="${device.id}" ${device.status!=="ONLINE"?"disabled":""}>เปลี่ยนเครือข่าย Wi-Fi</button><button class="outline" data-hw-usb-recovery="${device.id}">${device.credentialStatus==="REAUTHENTICATION_REQUIRED"?"ยืนยันอุปกรณ์อีกครั้ง":"กู้คืน Wi-Fi ผ่าน USB"}</button><button class="outline" data-hw-replace="${device.id}">เปลี่ยนกล่องควบคุม</button><button class="outline" data-hw-edit="${device.id}">แก้ไข</button><button class="outline" data-hw-alloff="${device.id}" ${device.status!=="ONLINE"?"disabled":""}>ปิด Relay ทั้งหมด</button><button class="danger" data-hw-delete="${device.id}">ลบ</button></div>
  </div>`).join("")||'<div class="card muted">ยังไม่มีอุปกรณ์ กด “เพิ่มอุปกรณ์” เพื่อเริ่มต้น</div>';
  const mappings=(state.tables||[]).map(table=>{const archivedCurrent=table.hardwareDeviceId&&archivedDevices.find(device=>device.id===table.hardwareDeviceId);const options=liveDevices.map(device=>`<option value="${device.id}" ${table.hardwareDeviceId===device.id?"selected":""}>${escapeHtml(device.deviceName)}</option>`).join("")+(archivedCurrent?`<option value="${archivedCurrent.id}" selected>${escapeHtml(archivedCurrent.deviceName)} (เปลี่ยนแทนแล้ว)</option>`:"");return `<tr><td>${escapeHtml(table.name)}</td><td><select data-map-device="${table.id}"><option value="">ยังไม่ผูก</option>${options}</select></td><td><select data-map-channel="${table.id}">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${Number(table.relayChannel)===i+1?"selected":""}>${i+1}</option>`).join("")}</select></td><td><button data-map-save="${table.id}">บันทึก</button></td></tr>`;}).join("");
  const archivedSection=archivedDevices.length?`<div class="card muted" style="margin-top:18px"><h3>อุปกรณ์ที่เปลี่ยนแทนแล้ว</h3><table><tr><th>ชื่อ</th><th>Device ID</th><th>แทนที่โดย</th><th>วันที่เปลี่ยน</th></tr>${archivedDevices.map(device=>`<tr><td>${escapeHtml(device.deviceName)}</td><td>${escapeHtml(device.deviceId||"-")}</td><td>${escapeHtml(hardwareDevices.find(item=>item.id===device.replacementDeviceId)?.deviceName||"-")}</td><td>${device.replacedAt?new Date(device.replacedAt).toLocaleString("th-TH"):"-"}</td></tr>`).join("")}</table></div>`:"";
  return `<div class="actions hardware-heading"><div><h3>Hardware Manager</h3><p class="muted">จัดการและทดสอบอุปกรณ์ควบคุมไฟโต๊ะ</p></div><div class="actions"><button id="usbFlasher" class="outline">ติดตั้ง/อัปเดต Firmware ผ่าน USB</button><button id="addHardware">เพิ่มอุปกรณ์</button></div></div><div class="hardware-grid">${cards}</div><div class="card" style="margin-top:18px"><h3>ผูก Relay กับโต๊ะ</h3><table><tr><th>โต๊ะ</th><th>อุปกรณ์</th><th>ช่อง Relay</th><th></th></tr>${mappings}</table></div>${archivedSection}`;
}
function hardwareDialog(device=null){
  openModal(`<h3>${device?"แก้ไข":"เพิ่ม"}อุปกรณ์ Relay Controller</h3><form id="hardwareForm"><label>ชื่ออุปกรณ์</label><input name="deviceName" value="${escapeHtml(device?.deviceName||"")}" required><label>IP Address</label><input name="ipAddress" value="${escapeHtml(device?.ipAddress||"")}" placeholder="192.168.1.50" required><label>Port</label><input name="port" type="number" min="1" max="65535" value="${device?.port||80}" required><label>API Key ${device?"(เว้นว่างเพื่อใช้ค่าเดิม)":""}</label><input name="apiKey" type="password" ${device?"":"required"} autocomplete="new-password"><label>Device Type</label><select name="deviceType"><option value="RELAY_CONTROLLER">RELAY_CONTROLLER</option></select><div id="hardwareTestResult" class="muted"></div><div class="actions"><button type="button" id="testHardwareCandidate" class="outline">Test Connection</button><button>Save</button><button type="button" id="cancelHardware">Cancel</button></div></form>`);
  const form=$("#hardwareForm"),payload=()=>{const d=Object.fromEntries(new FormData(form));d.port=Number(d.port);if(!d.apiKey)delete d.apiKey;if(device)d.existingDeviceId=device.id;return d;};
  $("#cancelHardware").onclick=closeModal;
  $("#testHardwareCandidate").onclick=async()=>{const result=$("#hardwareTestResult");result.textContent="กำลังทดสอบ…";try{await api("/api/hardware/devices/test-connection",{method:"POST",body:JSON.stringify(payload())});result.textContent="เชื่อมต่อสำเร็จ";}catch(error){result.textContent=error.message;}};
  form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button:not([type="button"])');button.disabled=true;try{await api(device?`/api/hardware/devices/${device.id}`:"/api/hardware/devices",{method:device?"PUT":"POST",body:JSON.stringify(payload())});closeModal();await loadHardware();notify("บันทึกอุปกรณ์แล้ว");}catch(error){notify(error.message,true);button.disabled=false;}};
}
async function enrollHardwareKey(deviceId){if(!confirm("ระบบจะสร้างรหัสเฉพาะกล่องและไม่แสดงรหัสเต็ม ต้องการดำเนินการหรือไม่?"))return;try{await api(`/api/hardware/devices/${deviceId}/key/enroll`,{method:"POST",body:"{}"});await loadHardware();notify("สร้างและตรวจสอบรหัสอุปกรณ์เฉพาะกล่องแล้ว");}catch(error){notify(error.message,true);}}
async function enrollSetupCode(deviceId){if(!confirm("Relay ทุกช่องต้อง OFF ระบบจะสร้าง Base31 Setup Code ใหม่และรหัสเดิมจะใช้ไม่ได้หลังสำเร็จ ต้องการดำเนินการหรือไม่?"))return;try{const result=await api(`/api/hardware/devices/${deviceId}/setup-code/enroll`,{method:"POST",body:"{}"});openModal(`<h3>Setup Code — แสดงครั้งเดียว</h3><p class="wizard-status warning">จดหรือพิมพ์รหัสนี้เก็บไว้ รหัสใช้สำหรับเข้า Wi-Fi ของกล่องและ Portal จึงไม่ใช่ two-factor authentication</p><div class="stat" style="letter-spacing:.12em">${escapeHtml(result.setupCode)}</div><label class="checkbox-line"><input id="setupCodeRecorded" type="checkbox"> ฉันบันทึก Setup Code ไว้แล้ว</label><button id="setupCodeDone" disabled>ยืนยันและปิด</button>`);$("#setupCodeRecorded").onchange=e=>$("#setupCodeDone").disabled=!e.target.checked;$("#setupCodeDone").onclick=async()=>{try{await api(`/api/hardware/devices/${deviceId}/setup-code/acknowledge`,{method:"POST",body:"{}"});closeModal();await loadHardware();notify("บันทึกการยืนยัน Setup Code แล้ว");}catch(error){notify(error.message,true);}};}catch(error){notify(error.message,true);}}
async function openSetupMode(deviceId){try{const status=await api(`/api/hardware/devices/${deviceId}/setup-mode`);openModal(`<h3>โหมดกู้คืน Wi-Fi</h3><p>สถานะ: <b>${escapeHtml(status.state)}</b></p>${status.active?`<p>เชื่อมต่อ Wi-Fi <b>${escapeHtml(status.ssid)}</b> แล้วเปิด <b>http://192.168.4.1</b><br>เหลือเวลาประมาณ ${Math.ceil((status.remainingSeconds||0)/60)} นาที</p><button id="setupModeStop" class="danger">ปิด Setup Mode</button>`:`<p>ก่อนเปิดต้องปิดโต๊ะผ่าน workflow ปกติจน Relay ทุกช่อง OFF ระบบจะไม่ปิด Relay ให้อัตโนมัติ</p><label class="checkbox-line"><input id="setupModeConfirmed" type="checkbox"> ยืนยันว่า Relay ทุกช่อง OFF และต้องการเปิด Setup AP</label><button id="setupModeStart">เปิดโหมดตั้งค่า Wi-Fi</button>`}<button id="setupModeClose" class="outline">ปิดหน้าต่าง</button>`);$("#setupModeClose").onclick=closeModal;if(status.active)$("#setupModeStop").onclick=async()=>{try{await api(`/api/hardware/devices/${deviceId}/setup-mode/stop`,{method:"POST",body:"{}"});notify("ปิด Setup Mode แล้ว");closeModal();}catch(error){notify(error.message,true);}};else $("#setupModeStart").onclick=async event=>{if(!$("#setupModeConfirmed").checked)return notify("กรุณายืนยันความปลอดภัยก่อน",true);event.target.disabled=true;try{await api(`/api/hardware/devices/${deviceId}/setup-mode/start`,{method:"POST",body:JSON.stringify({confirmed:true})});notify("กำลังเปิด Setup AP");setTimeout(()=>openSetupMode(deviceId),1000);}catch(error){notify(error.message,true);event.target.disabled=false;}};}catch(error){notify(error.message,true);}}
async function openWifiChange(deviceId){openModal(`<h3>เปลี่ยนเครือข่าย Wi-Fi</h3><div class="wizard-loading">กำลังค้นหาเครือข่าย กรุณารอสักครู่…</div>`);try{let scan=await api(`/api/hardware/devices/${deviceId}/wifi/networks`);for(let i=0;i<20&&scan.scanning;i+=1){await new Promise(resolve=>setTimeout(resolve,500));scan=await api(`/api/hardware/devices/${deviceId}/wifi/networks`);}const options=(scan.networks||[]).map(item=>`<option value="${escapeHtml(item.ssid)}">${escapeHtml(item.ssid||"(เครือข่ายซ่อน)")} — ${item.rssi} dBm</option>`).join("");openModal(`<h3>เปลี่ยนเครือข่าย Wi-Fi</h3><form id="wifiChangeForm"><label>เครือข่าย</label><select name="ssid">${options}</select><label>หรือกรอกชื่อเครือข่าย</label><input name="manualSsid" maxlength="32"><label>รหัสผ่าน Wi-Fi</label><input name="password" type="password" maxlength="63" autocomplete="new-password"><label class="checkbox-line"><input name="confirmedSafe" type="checkbox"> ยืนยันว่าไม่มีโต๊ะกำลังใช้งานและ Relay ทุกช่องปิดอยู่</label><div class="wizard-status warning">หากมี Relay เปิดอยู่ ระบบจะปฏิเสธและจะไม่ปิด Relay ให้อัตโนมัติ</div><div class="actions"><button>เริ่มเปลี่ยน Wi-Fi</button><button type="button" class="outline" id="wifiChangeCancel">ยกเลิก</button></div></form>`);$("#wifiChangeCancel").onclick=closeModal;$("#wifiChangeForm").onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const ssid=String(data.manualSsid||data.ssid||"").trim();if(!ssid||data.confirmedSafe!=="on")return notify("กรุณาเลือกเครือข่ายและยืนยันความปลอดภัย",true);try{const session=await api(`/api/hardware/devices/${deviceId}/wifi/start`,{method:"POST",body:JSON.stringify({ssid,password:data.password||"",confirmedSafe:true})});event.target.reset();renderWifiProgress(session);}catch(error){notify(error.message,true);}};}catch(error){closeModal();notify(error.message,true);}}
function renderWifiProgress(session){openModal(`<h3>เปลี่ยนเครือข่าย Wi-Fi</h3><div class="${session.state==="FAILED"?"wizard-error":"wizard-loading"}">${escapeHtml(session.message)}</div><p>สถานะ: ${escapeHtml(session.state)}</p><button class="outline" id="wifiProgressClose">ปิด</button>`);$("#wifiProgressClose").onclick=closeModal;if(!["COMPLETED","FAILED"].includes(session.state))setTimeout(async()=>{try{renderWifiProgress(await api(`/api/hardware/wifi/${session.id}`));}catch(error){notify(error.message,true);}},1000);else loadHardware(true);}
async function openUsbRecovery(deviceId){try{const [ports,binding]=await Promise.all([api("/api/hardware/usb-flasher/ports"),api(`/api/hardware/devices/${deviceId}/usb-recovery/token`,{method:"POST",body:"{}"})]);const options=(ports.ports||[]).map(item=>`<option value="${escapeHtml(item.port)}">${escapeHtml(item.name||item.port)}</option>`).join("");const device=hardwareDevices.find(item=>item.id===deviceId),reauth=device?.credentialStatus==="REAUTHENTICATION_REQUIRED";openModal(`<h3>${reauth?"ยืนยันอุปกรณ์อีกครั้ง":"กู้คืน Wi-Fi ผ่าน USB"}</h3><div class="wizard-status warning">Relay ทุกช่องต้อง OFF ระบบจะไม่สั่งปิด Relay ให้อัตโนมัติ</div><form id="usbRecoveryForm"><label>COM Port</label><select name="port" required><option value="">เลือก COM Port</option>${options}</select>${reauth?'<label>Setup Code</label><input name="setupCode" type="password" autocomplete="off" required>':'<label>ชื่อ Wi-Fi</label><input name="ssid" maxlength="32" required><label>รหัสผ่าน Wi-Fi</label><input name="password" type="password" maxlength="63" autocomplete="new-password">'}<label class="checkbox-line"><input name="confirmed" type="checkbox" required> ยืนยันว่าปิดโต๊ะและ Relay ทุกช่องแล้ว</label><button>เริ่มดำเนินการ</button></form>`);$("#usbRecoveryForm").onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));if(data.confirmed!=="on")return notify("กรุณายืนยันความปลอดภัยก่อน",true);try{const result=await api(reauth?"/api/hardware/usb-recovery/key-rotation":"/api/hardware/usb-recovery/wifi",{method:"POST",body:JSON.stringify({recoveryToken:binding.recoveryToken,port:data.port,setupCode:data.setupCode,ssid:data.ssid,password:data.password})});event.target.reset();openModal(`<h3>${reauth?"ยืนยันอุปกรณ์อีกครั้ง":"กู้คืน Wi-Fi ผ่าน USB"}</h3><p>สถานะ: ${escapeHtml(result.state)}</p>${result.message?`<p class="wizard-error">${escapeHtml(result.message)}</p>`:""}<button id="usbRecoveryDone">ปิด</button>`);$("#usbRecoveryDone").onclick=()=>{closeModal();loadHardware(true);};}catch(error){event.target.reset();notify(error.message,true);}};}catch(error){notify(error.message,true);}}
async function replaceHardwareDevice(oldId){const candidates=hardwareDevices.filter(item=>item.id!==oldId&&item.status==="ONLINE"&&item.credentialStatus!=="REAUTHENTICATION_REQUIRED");if(!candidates.length)return notify("ยังไม่มีกล่องใหม่ที่ยืนยันตัวตนแล้วสำหรับเปลี่ยนแทน",true);openModal(`<h3>เปลี่ยนกล่องควบคุม</h3><form id="replaceHardwareForm"><label>กล่องใหม่</label><select name="replacementRecordId">${candidates.map(item=>`<option value="${item.id}">${escapeHtml(item.deviceName)} — ${escapeHtml(item.deviceId)}</option>`).join("")}</select><div class="wizard-status warning">ระบบจะตรวจ Relay ทุกช่องซ้ำและย้าย mapping แบบ atomic กล่องเดิมจะถูกเก็บเป็น REPLACED_ARCHIVED</div><label class="checkbox-line"><input name="confirmed" type="checkbox"> ยืนยันการเปลี่ยนกล่องควบคุม</label><button>ตรวจสอบและเปลี่ยนกล่อง</button></form>`);$("#replaceHardwareForm").onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));if(data.confirmed!=="on")return notify("กรุณายืนยันการเปลี่ยนกล่อง",true);try{await api(`/api/hardware/devices/${oldId}/replace`,{method:"POST",body:JSON.stringify({replacementRecordId:data.replacementRecordId,confirmed:true})});closeModal();await loadHardware(true);notify("เปลี่ยนกล่องควบคุมและย้าย mapping สำเร็จ");}catch(error){notify(error.message,true);}};}
async function openUsbFlasher(){
  try{
    try{const active=await api("/api/hardware/usb-flasher/active");return renderUsbFlashProgress(active);}catch(error){if(error.code!=="FLASH_OPERATION_NOT_FOUND")throw error;}
    const {ports}=await api("/api/hardware/usb-flasher/ports");
    const options=ports.map(item=>`<option value="${escapeHtml(item.port)}">${escapeHtml(item.port)} — ${escapeHtml(item.manufacturer||item.name||"ไม่ทราบผู้ผลิต")} ${item.vid?`(${item.vid}:${item.pid})`:""}</option>`).join("");
    openModal(`<h3>ติดตั้ง Firmware ผ่าน USB</h3><div class="wizard-status warning">ถอดโหลดไฟบ้านออกจาก Relay และปิดโต๊ะทุกโต๊ะก่อนเชื่อมต่อ USB</div><form id="usbFlashForm"><label>COM Port</label><select name="port" required><option value="">เลือกพอร์ตด้วยตนเอง</option>${options}</select><label>วิธีดำเนินการ</label><select name="mode"><option value="update">อัปเดตกล่องเดิม — รักษาการตั้งค่าทั้งหมด</option><option value="new">ติดตั้งกล่องใหม่ — ลบข้อมูลเดิมในกล่อง</option></select><label class="checkbox-line"><input name="safe" type="checkbox"> ยืนยันว่าปิดโต๊ะทั้งหมดและถอดโหลดไฟบ้านแล้ว</label><div id="newInstallConfirm" class="hidden"><label>Relay board</label><select name="relayCount"><option value="">เลือกจำนวนช่อง</option><option value="2">2 ช่อง</option><option value="4">4 ช่อง</option><option value="8">8 ช่อง</option></select><p class="wizard-error">การติดตั้งกล่องใหม่จะลบข้อมูลเดิมในกล่อง</p><label>พิมพ์ ERASE NEW DEVICE เพื่อยืนยัน</label><input name="destructiveConfirmation" autocomplete="off"></div><div class="actions"><button>ตรวจสอบและเริ่ม</button><button type="button" id="usbFlashClose" class="outline">ยกเลิก</button></div></form>`);
    const form=$("#usbFlashForm"),mode=form.elements.mode;
    const recoveryOption=document.createElement("option");recoveryOption.value="recover";recoveryOption.textContent="ตรวจสอบงานอัปเดตเดิมต่อ — ไม่ Flash ซ้ำ";mode.append(recoveryOption);
    mode.onchange=()=>$("#newInstallConfirm").classList.toggle("hidden",mode.value!=="new");$("#usbFlashClose").onclick=closeModal;
    form.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));if(data.safe!=="on")return notify("กรุณายืนยันความปลอดภัยก่อน",true);if(data.mode==="new"&&!["2","4","8"].includes(data.relayCount))return notify("กรุณาเลือกจำนวน Relay",true);try{const csrf=await api("/api/hardware/usb-flasher/csrf");const tokenResponse=await fetch("/api/hardware/usb-flasher/token",{method:"POST",headers:{"Content-Type":"application/json","X-Lucky-CSRF":csrf.csrfToken},body:"{}"});const token=await tokenResponse.json();if(!tokenResponse.ok)throw Error(token.message||token.error);const operation=await api("/api/hardware/usb-flasher/start",{method:"POST",body:JSON.stringify({mode:data.mode,port:data.port,relayCount:Number(data.relayCount),destructiveConfirmation:data.destructiveConfirmation,operationToken:token.operationToken})});renderUsbFlashProgress(operation);}catch(error){notify(error.message,true);}};
  }catch(error){notify(error.message,true);}
}
function renderUsbFlashProgress(operation){const pending=operation.state==="ENROLLMENT_PENDING",terminal=["COMPLETED","FAILED","CANCELLED","ENROLLMENT_RECOVERY_REQUIRED"].includes(operation.state),polling=!terminal&&(!pending||operation.enrollmentRunning);openModal(`<h3>${pending?"ตั้งค่ากล่องใหม่ต่อ":"กำลังติดตั้ง Firmware"}</h3><p>สถานะ: <b>${escapeHtml(operation.enrollmentState||operation.state)}</b></p><progress value="${Number(operation.progress||0)}" max="100" style="width:100%"></progress>${operation.message?`<p class="wizard-error">${escapeHtml(operation.message)}</p>`:""}${operation.enrollmentMessage?`<p class="${operation.enrollmentState==="RETRY_REQUIRED"?"wizard-error":"wizard-status warning"}">${escapeHtml(operation.enrollmentMessage)}</p>`:""}${operation.setupCode?`<div class="wizard-status warning">Setup Code แสดงครั้งเดียว กรุณาจดเก็บไว้</div><div class="stat">${escapeHtml(operation.setupCode)}</div>`:""}${pending&&!operation.enrollmentRunning?'<div class="wizard-status warning"><b>ห้ามปิด Server ระหว่าง Enrollment Pending</b><br>เชื่อมต่อ Setup AP และตั้ง Wi-Fi ผ่าน Portal ให้เสร็จก่อน แล้วจึงค้นหากล่องจากเครื่อง Server นี้</div><button id="usbEnrollmentContinue">ดำเนินการตั้งค่ากล่องต่อ</button>':""}${operation.state==="COMPLETED"&&operation.enrollmentWizard?'<button id="usbEnrollmentWizard">ตรวจสายและตั้งชื่อกล่องต่อ</button>':""}<button id="usbFlashDone" class="outline">${terminal?"ปิด":"ซ่อนหน้าต่าง"}</button>`);$("#usbFlashDone").onclick=closeModal;$("#usbEnrollmentContinue")&&($("#usbEnrollmentContinue").onclick=()=>beginEnrollmentHandoff(operation));$("#usbEnrollmentWizard")&&($("#usbEnrollmentWizard").onclick=()=>{hardwareWizard={...operation.enrollmentWizard,stepNumber:5};renderHardwareWizard();});if(polling)setTimeout(async()=>{try{renderUsbFlashProgress(await api(`/api/hardware/usb-flasher/${operation.id}`));}catch(error){notify(error.code==="FLASH_OPERATION_NOT_FOUND"?"Server ถูกเริ่มใหม่และข้อมูล Enrollment ในหน่วยความจำหายแล้ว กรุณาใช้ขั้นตอน recovery สำหรับ Test Hardware":error.message,true);}},700);}
async function beginEnrollmentHandoff(operation){if(!confirm("ยืนยันว่าตั้งค่า Wi-Fi ผ่าน Setup Portal สำเร็จแล้ว และ Server จะเปิดค้างไว้ระหว่างค้นหา?"))return;try{const token=await api(`/api/hardware/usb-flasher/${operation.id}/enrollment/token`,{method:"POST",body:"{}"});const response=await fetch(`/api/hardware/usb-flasher/${operation.id}/enrollment/start`,{method:"POST",headers:{"Content-Type":"application/json","X-Lucky-Enrollment-Token":token.enrollmentToken},body:"{}"}),data=await response.json();if(!response.ok)throw Object.assign(Error(data.message||data.error),{code:data.error});renderUsbFlashProgress(data);}catch(error){notify(error.message,true);}}
const renderUsbFlashProgressBase=renderUsbFlashProgress;
renderUsbFlashProgress=function(operation){if(dismissedUsbFlashOperations.has(operation.id))return;currentUsbFlashOperation=operation;return renderUsbFlashProgressBase(operation);};
let wiringAssistant=null;
async function openWiringAssistant(deviceId){try{wiringAssistant={deviceId,step:1,view:await api(`/api/hardware/devices/${deviceId}/wiring`),session:null};renderWiringAssistant();}catch(error){notify(error.message,true);}}
function wiringRows(mapping,interactive=false){return `<table class="wiring-table"><tr><th>Relay</th><th>ESP32 GPIO</th><th>Relay input</th><th>สถานะ</th><th></th></tr>${mapping.map(item=>`<tr><td>Relay ${item.relayChannel}</td><td>GPIO${item.gpio}</td><td>${item.inputLabel}</td><td>${escapeHtml(item.verificationStatus||"NOT_TESTED")}${item.actualChannel?` — ทำงานจริง IN${item.actualChannel}`:""}</td><td>${interactive?`<button data-wiring-test="${item.relayChannel}" ${(wiringAssistant.session?.state!=="READY")?"disabled":""}>เริ่มทดสอบ Relay ${item.relayChannel}</button>`:""}</td></tr>`).join("")}</table>`;}
function renderWiringAssistant(){const w=wiringAssistant,d=w.view.device;if(w.step===1){openModal(`<h3>ตรวจสอบการต่อสาย — ขั้นที่ 1</h3><p><b>${escapeHtml(d.deviceName)}</b><br>Device ID: ${escapeHtml(d.deviceId)}<br>IP: ${escapeHtml(d.ipAddress)}<br>สถานะ: ${escapeHtml(d.status)}<br>Firmware: ${escapeHtml(d.firmwareVersion||"-")}<br>Relay: ${d.relayCount} ช่อง<br>Hardware Standard: ${escapeHtml(w.view.hardwareStandard)}<br>ตรวจสายล่าสุด: ${d.lastWiringVerifiedAt?new Date(d.lastWiringVerifiedAt).toLocaleString("th-TH"):"ยังไม่เคยตรวจ"}</p><button id="wiringNext">ถัดไป</button><button class="outline" id="wiringClose">ปิด</button>`);$("#wiringNext").onclick=()=>{w.step=2;renderWiringAssistant();};$("#wiringClose").onclick=closeModal;return;}if(w.step===2){const checks=["ปิดโต๊ะทุกโต๊ะผ่าน workflow ปกติแล้ว","ไม่มี Active Table Session ที่ผูกกับกล่องนี้","ถอดโหลดไฟบ้านออกแล้ว","Relay ทุกช่องอยู่ OFF","พร้อมทดสอบทีละช่อง"];openModal(`<h3>คำเตือนความปลอดภัย — ขั้นที่ 2</h3><div class="wizard-status warning"><b>ถอดโหลดไฟบ้านออกจาก Relay ทุกช่อง</b><br>ใช้เฉพาะไฟแรงดันต่ำระหว่างการทดสอบ<br>ระบบจะสั่ง Relay ทำงานจริงทีละช่อง<br>ระบบจะไม่สั่งปิด Relay ทั้งหมดให้อัตโนมัติ</div>${checks.map((label,index)=>`<label class="checkbox-line"><input type="checkbox" data-wiring-confirm="${index}"> ${label}</label>`).join("")}<button id="wiringStart" disabled>เริ่มตรวจสาย</button><button class="outline" id="wiringBack">ย้อนกลับ</button>`);const boxes=[...document.querySelectorAll("[data-wiring-confirm]")];boxes.forEach(box=>box.onchange=()=>$("#wiringStart").disabled=!boxes.every(item=>item.checked));$("#wiringBack").onclick=()=>{w.step=1;renderWiringAssistant();};$("#wiringStart").onclick=async()=>{try{w.session=await api(`/api/hardware/devices/${w.deviceId}/wiring/session`,{method:"POST",body:JSON.stringify({confirmations:{tablesClosed:true,noActiveSessions:true,mainsDisconnected:true,relaysOff:true,readyForSingleChannelTest:true}})});w.step=3;renderWiringAssistant();}catch(error){notify(error.message,true);}};return;}const emergency=w.session?.emergency;openModal(`<h3>ผังสายและการทดสอบ — ขั้นที่ 3–4</h3>${emergency?`<div class="wiring-emergency"><b>หยุดทดสอบทันที</b><br>${escapeHtml(emergency.message)}</div>`:""}${wiringRows(w.session.mapping,true)}<p class="muted">สีสายเป็นเพียงตัวช่วย ต้องติดป้ายทั้งสองปลายเสมอ เช่น R1 / GPIO13 / IN1</p><div class="actions"><button id="wiringComplete" ${w.session.state!=="READY"||emergency?"disabled":""}>บันทึกผล</button><button class="outline" id="wiringCancel" ${emergency?"disabled":""}>ยกเลิก</button></div>`);document.querySelectorAll("[data-wiring-test]").forEach(button=>button.onclick=()=>runWiringPulse(Number(button.dataset.wiringTest)));$("#wiringComplete").onclick=completeWiringAssistant;$("#wiringCancel").onclick=cancelWiringAssistant;}
async function runWiringPulse(channel){try{wiringAssistant.session=await api(`/api/hardware/devices/${wiringAssistant.deviceId}/wiring/test`,{method:"POST",body:JSON.stringify({sessionId:wiringAssistant.session.id,channel})});openModal(`<h3>ยืนยันผล Relay ${channel}</h3><p>ไฟ/เสียงคลิกเกิดที่ช่อง IN${channel} หรือไม่?</p><select id="wiringResult"><option value="VERIFIED">ถูกต้อง</option><option value="MISMATCH">ไม่ถูกต้อง</option><option value="UNCERTAIN">ไม่แน่ใจ</option><option value="SKIPPED">ข้ามก่อน</option></select><label>ช่องที่ทำงานจริง (เมื่อไม่ถูกต้อง)</label><select id="wiringActual"><option value="">เลือกช่อง</option>${wiringAssistant.session.mapping.filter(item=>item.relayChannel!==channel).map(item=>`<option value="${item.relayChannel}">IN${item.relayChannel}</option>`).join("")}</select><button id="wiringResultSave">บันทึกผล</button>`);$("#wiringResultSave").onclick=async()=>{try{wiringAssistant.session=await api(`/api/hardware/devices/${wiringAssistant.deviceId}/wiring/result`,{method:"POST",body:JSON.stringify({sessionId:wiringAssistant.session.id,channel,status:$("#wiringResult").value,actualChannel:Number($("#wiringActual").value)||undefined})});renderWiringAssistant();}catch(error){notify(error.message,true);}};}catch(error){if(error.emergency)wiringAssistant.session.emergency=error.emergency;notify(error.message,true);renderWiringAssistant();}}
