async function completeWiringAssistant(){try{const result=await api(`/api/hardware/devices/${wiringAssistant.deviceId}/wiring/complete`,{method:"POST",body:JSON.stringify({sessionId:wiringAssistant.session.id})});wiringAssistant.view=result.sheet;wiringAssistant.session.mapping=result.wiringProfile.mapping;renderWiringSheet(result.sheet,result.wiringProfile);await loadHardware(true);}catch(error){notify(error.message,true);}}
