// Booking for a member should not ask staff to retype the name and phone the member record already
// holds — that is how a booking ends up under a misspelling of a customer who is already in the
// system. Selecting a member fills both fields from the record and locks them.
//
// The one thing that cannot be filled is a phone the member does not have. A phone reservation is
// unusable without a number to call back, so that field stays open, stays required, and says why.
function applyReservationMember10f(member){
  const form=$("#reservationForm"); if(!form)return;
  const nameField=form.elements.customerName, phoneField=form.elements.phone;
  const hint=$("#reservationMemberPhoneHint"), clear=$("#reservationMemberClear");
  if(!member){
    [nameField,phoneField].forEach(field=>{if(!field)return;field.readOnly=false;field.value="";field.required=true;field.classList.remove("prefilled");});
    if(hint)hint.textContent="";
    if(clear)clear.classList.add("hidden");
    return;
  }
  const name=member.displayName||member.name||"", phone=String(member.phone||"").trim();
  if(nameField){nameField.value=name;nameField.readOnly=true;nameField.required=true;nameField.classList.add("prefilled");}
  if(phoneField){
    phoneField.value=phone;
    phoneField.readOnly=Boolean(phone);
    phoneField.required=true;                       // required either way — the server enforces it too
    phoneField.classList.toggle("prefilled",Boolean(phone));
  }
  if(hint)hint.textContent=phone?"":"สมาชิกรายนี้ไม่มีเบอร์โทรในระบบ — กรุณากรอกเบอร์โทรเพื่อยืนยันการจอง";
  if(clear)clear.classList.remove("hidden");
  if(!phone&&phoneField)phoneField.focus();
}
